package tw.eternalforge.command;
import org.bukkit.Bukkit;import org.bukkit.command.*;import org.bukkit.entity.Player;import tw.eternalforge.EternalForgePlugin;import tw.eternalforge.gui.ForgeMenu;import tw.eternalforge.history.ForgeHistory;import tw.eternalforge.util.Text;import java.util.*;
public final class ForgeCommand implements CommandExecutor,TabCompleter{private final EternalForgePlugin plugin;private final ForgeMenu menu;private final ForgeHistory history;public ForgeCommand(EternalForgePlugin p,ForgeMenu m,ForgeHistory h){plugin=p;menu=m;history=h;}
 public boolean onCommand(CommandSender s,Command c,String l,String[] a){if(a.length>0&&a[0].equalsIgnoreCase("reload")){if(!admin(s))return true;plugin.reloadAll();s.sendMessage(Text.c("&aEternalForge 3.4.0 所有設定檔已重新載入。"));return true;}if(a.length>1&&a[0].equalsIgnoreCase("open")){if(!admin(s))return true;Player t=Bukkit.getPlayerExact(a[1]);if(t==null){s.sendMessage(Text.c("&c找不到在線玩家：&f"+a[1]));return true;}menu.open(t);return true;}if(a.length>0&&a[0].equalsIgnoreCase("history")){if(!admin(s))return true;String n=a.length>1?a[1]:null;int lim=Math.max(1,Math.min(50,plugin.getConfig().getInt("history.command-limit",10)));s.sendMessage(Text.c("&8&m-----&r &bEternalForge 強化紀錄 &8&m-----"));for(String line:history.recent(n,lim)){String[] p=line.split("\\t");if(p.length>=8)s.sendMessage(Text.c("&8[&7"+p[0]+"&8] &e"+p[2]+" &f"+p[3]+" &7+"+p[5]+" → &6"+(p[6].equals("-1")?"損壞":"+"+p[6])+" &8("+p[4]+", "+p[7]+"%)"));}return true;}if(a.length>0&&a[0].equalsIgnoreCase("debug")){if(!admin(s))return true;s.sendMessage(Text.c("&bEternalForge 3.4.0 Modular Config Edition &7Paper="+Bukkit.getVersion()));return true;}if(!(s instanceof Player p)){s.sendMessage("/forge open <player> | history [player] | reload | debug");return true;}if(!p.hasPermission("eternalforge.use")){p.sendMessage(Text.c(plugin.configs().messages().getString("no-permission","&c沒有權限。")));return true;}menu.open(p);return true;}
 private boolean admin(CommandSender s){if(s.hasPermission("eternalforge.admin"))return true;s.sendMessage(Text.c(plugin.configs().messages().getString("no-permission","&c沒有權限。")));return false;}public List<String> onTabComplete(CommandSender s,Command c,String l,String[] a){if(!s.hasPermission("eternalforge.admin"))return List.of();if(a.length==1)return List.of("open","history","reload","debug");if(a.length==2&&(a[0].equalsIgnoreCase("open")||a[0].equalsIgnoreCase("history"))){List<String> n=new ArrayList<>();for(Player p:Bukkit.getOnlinePlayers())n.add(p.getName());return n;}return List.of();}}
